#### Example 2: Pattern Integration in Application Startup

```csharp
public class Startup
{
    public void ConfigureServices(IServiceCollection services)
    {
        // Core Architecture Pattern: Tenant Context Management
        services.AddTenantContext(options =>
        {
            options.IdentificationStrategy = TenantIdentificationStrategy.Subdomain;
            options.UseAsyncLocalStorage = true;
        });

        // Data Isolation Pattern: Factory for tenant-specific data access
        services.AddTenantDataAccess(options =>
        {
            options.DefaultIsolationStrategy = IsolationStrategy.SchemaPerTenant;
            options.ConnectionPoolSize = 50;
        });

        // Compliance & Security Pattern: Audit logging
        services.AddAuditLogging(options =>
        {
            options.LogAllTenantOperations = true;
            options.IncludePHIAccess = true;
            options.RetentionDays = 2555; // 7 years for HIPAA
        });

        // Automation & Validation Pattern: Health checks
        services.AddHealthChecks()
            .AddTenantIsolationCheck()
            .AddComplianceCheck();
    }
}
